    /// <summary>
    /// MPJ_3173 - nciantar - 09/04/2021
    /// Caption visible according to FSD 3173
    /// </summary>
    protected void new()
    {
        super();

        this.parmClassName(classStr(METCustIntStockTransferService));
        this.parmMethodName(methodStr(METCustIntStockTransferService, processOperation));
        this.parmDialogCaption("@MET:CustIntStockTransfer");
    }

/// <summary>
/// MPJ_3173 - nciantar - 09/04/2021
/// Automatically populates the batch text required by user before submitting to batch
/// </summary>
/// <returns>caption</returns>
public ClassDescription caption()
{
    return "@MET:CustIntStockTransfer";
}

    /// <summary>
    /// MPJ_3173 - nciantar - 09/04/2021
    /// Main method required to run the opration
    /// </summary>
    /// <param name = "args">Args</param>
    public static void main(Args args)
    {
        METCustIntStockTransferController controller;

        controller = new METCustIntStockTransferController();
        controller.parmArgs(args);

        controller.startOperation();
        
    }

/// <summary>
/// MPJ_3173 - nciantar - 09/04/2021
/// BP to have a constructor for new controller.
/// </summary>
/// <returns>Controller instance</returns>
public static METCustIntStockTransferController construct()
{
    return new METCustIntStockTransferController();
}
